"""
Longest Increasing Subsequence (LIS) Problems
Naive DP: O(n²) | Patience Sort: O(n log n)
"""

import bisect

# ---- O(n²) DP ----
def lis_dp(nums):
    if not nums: return 0
    dp = [1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

# ---- O(n log n) — Patience Sorting ----
def lis_optimized(nums):
    tails = []
    for num in nums:
        pos = bisect.bisect_left(tails, num)
        if pos == len(tails): tails.append(num)
        else: tails[pos] = num
    return len(tails)

# Reconstruct actual LIS sequence
def lis_sequence(nums):
    if not nums: return []
    n = len(nums)
    dp = [1] * n
    parent = [-1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                parent[i] = j
    max_len = max(dp)
    idx = dp.index(max_len)
    seq = []
    while idx != -1:
        seq.append(nums[idx])
        idx = parent[idx]
    return seq[::-1]

# Number of LIS
def number_of_lis(nums):
    n = len(nums)
    dp = [1] * n    # lengths
    count = [1] * n # counts
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    count[i] = count[j]
                elif dp[j] + 1 == dp[i]:
                    count[i] += count[j]
    max_len = max(dp)
    return sum(count[i] for i in range(n) if dp[i] == max_len)

# Longest Common Subsequence (LCS)
def lcs(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]: dp[i][j] = dp[i-1][j-1] + 1
            else: dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    # Reconstruct
    seq = []
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]: seq.append(s1[i-1]); i -= 1; j -= 1
        elif dp[i-1][j] > dp[i][j-1]: i -= 1
        else: j -= 1
    return ''.join(reversed(seq)), dp[m][n]

# Edit Distance (Levenshtein)
def edit_distance(word1, word2):
    m, n = len(word1), len(word2)
    dp = list(range(n+1))
    for i in range(1, m+1):
        prev = dp[:]
        dp[0] = i
        for j in range(1, n+1):
            if word1[i-1] == word2[j-1]: dp[j] = prev[j-1]
            else: dp[j] = 1 + min(prev[j], dp[j-1], prev[j-1])
    return dp[n]

if __name__ == '__main__':
    nums = [10,9,2,5,3,7,101,18]
    print(lis_dp(nums))         # 4
    print(lis_optimized(nums))  # 4
    print(lis_sequence(nums))   # [2,3,7,18] or [2,5,7,101]
    print(number_of_lis([1,3,5,4,7]))  # 2
    seq, length = lcs('ABCBDAB', 'BDCAB')
    print(seq, length)          # BCAB 4
    print(edit_distance('horse', 'ros'))  # 3

"""
Knapsack Variants and Coin Change
"""

# 1. Coin Change — min coins (unbounded)
def coin_change(coins, amount):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for a in range(coin, amount + 1):
            dp[a] = min(dp[a], dp[a - coin] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1

# 2. Coin Change II — number of combinations
def coin_change_ways(coins, amount):
    dp = [0] * (amount + 1)
    dp[0] = 1
    for coin in coins:
        for a in range(coin, amount + 1):
            dp[a] += dp[a - coin]
    return dp[amount]

# 3. 0/1 Knapsack
def knapsack_01(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            dp[i][w] = dp[i-1][w]
            if weights[i-1] <= w:
                dp[i][w] = max(dp[i][w], dp[i-1][w - weights[i-1]] + values[i-1])
    return dp[n][capacity]

# Space-optimized 0/1 Knapsack — O(W)
def knapsack_01_opt(weights, values, capacity):
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        for c in range(capacity, w - 1, -1):  # reverse to avoid using item twice
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[capacity]

# 4. Partition Equal Subset Sum
def can_partition(nums):
    total = sum(nums)
    if total % 2: return False
    target = total // 2
    dp = {0}
    for num in nums:
        dp = {s + num for s in dp} | dp
    return target in dp

# 5. Target Sum (assign +/- to each number)
def find_target_sum_ways(nums, target):
    dp = {0: 1}
    for num in nums:
        new_dp = {}
        for s, count in dp.items():
            new_dp[s + num] = new_dp.get(s + num, 0) + count
            new_dp[s - num] = new_dp.get(s - num, 0) + count
        dp = new_dp
    return dp.get(target, 0)

# 6. Minimum Cost to Cut a Stick (Interval DP)
def min_cost(n, cuts):
    cuts = sorted([0] + cuts + [n])
    m = len(cuts)
    dp = [[0] * m for _ in range(m)]
    for length in range(2, m):
        for left in range(m - length):
            right = left + length
            dp[left][right] = float('inf')
            for mid in range(left + 1, right):
                cost = cuts[right] - cuts[left] + dp[left][mid] + dp[mid][right]
                dp[left][right] = min(dp[left][right], cost)
    return dp[0][m-1]

if __name__ == '__main__':
    print(coin_change([1,5,11], 15))     # 3 (5+5+5)
    print(coin_change_ways([1,2,5], 5))  # 4
    print(knapsack_01([2,3,4,5],[3,4,5,6], 5))  # 7
    print(can_partition([1,5,11,5]))     # True
    print(find_target_sum_ways([1,1,1,1,1], 3))  # 5

"""
Graph Coloring, Bipartite Check, and Related Problems
"""

from collections import deque, defaultdict

# 1. Bipartite Check (2-colorable)
def is_bipartite(graph):
    color = {}
    for start in range(len(graph)):
        if start in color: continue
        queue = deque([start])
        color[start] = 0
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in color:
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False  # same color → not bipartite
    return True

# 2. M-Coloring (backtracking)
def m_coloring(graph, m, n):
    colors = [0] * n

    def is_safe(node, c):
        return all(colors[neighbor] != c for neighbor in graph[node])

    def solve(node):
        if node == n: return True
        for c in range(1, m + 1):
            if is_safe(node, c):
                colors[node] = c
                if solve(node + 1): return True
                colors[node] = 0
        return False

    return solve(0), colors

# 3. Is Graph a Tree? (connected + no cycle)
def is_tree(n, edges):
    if len(edges) != n - 1: return False
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    visited = set()
    def dfs(node, parent):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor == parent: continue
            if neighbor in visited: return False
            if not dfs(neighbor, node): return False
        return True
    return dfs(0, -1) and len(visited) == n

# 4. Detect Cycle in Directed Graph
def has_cycle_directed(n, edges):
    graph = defaultdict(list)
    for u, v in edges: graph[u].append(v)
    WHITE, GRAY, BLACK = 0, 1, 2
    state = [WHITE] * n
    def dfs(node):
        state[node] = GRAY
        for neighbor in graph[node]:
            if state[neighbor] == GRAY: return True   # back edge
            if state[neighbor] == WHITE and dfs(neighbor): return True
        state[node] = BLACK
        return False
    return any(dfs(i) for i in range(n) if state[i] == WHITE)

# 5. Clone Graph
class Node:
    def __init__(self, val=0, neighbors=None):
        self.val = val
        self.neighbors = neighbors or []

def clone_graph(node):
    if not node: return None
    clones = {}
    def dfs(n):
        if n in clones: return clones[n]
        clone = Node(n.val)
        clones[n] = clone
        for neighbor in n.neighbors:
            clone.neighbors.append(dfs(neighbor))
        return clone
    return dfs(node)

if __name__ == '__main__':
    g = [[1,3],[0,2],[1,3],[0,2]]
    print(is_bipartite(g))  # True (can 2-color)
    g2 = [[1,2,3],[0,2],[0,1,3],[0,2]]
    print(is_bipartite(g2)) # False (triangle)
    print(has_cycle_directed(4, [(0,1),(1,2),(2,3),(3,1)]))  # True
    print(is_tree(5, [(0,1),(0,2),(0,3),(1,4)]))  # True

"""
Palindrome Problems — Comprehensive Collection
"""

# 1. Longest Palindromic Subsequence
def longest_palindromic_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n): dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]: dp[i][j] = dp[i+1][j-1] + 2
            else: dp[i][j] = max(dp[i+1][j], dp[i][j-1])
    return dp[0][n-1]

# 2. Minimum insertions to make palindrome
def min_insertions_palindrome(s):
    return len(s) - longest_palindromic_subseq(s)

# 3. Palindrome Partitioning — min cuts
def min_cut(s):
    n = len(s)
    is_pal = [[False]*n for _ in range(n)]
    for i in range(n-1, -1, -1):
        for j in range(i, n):
            is_pal[i][j] = (s[i]==s[j] and (j-i<=2 or is_pal[i+1][j-1]))
    dp = list(range(-1, n-1))  # dp[i] = min cuts for s[0..i]
    for i in range(n):
        for j in range(i+1):
            if is_pal[j][i]:
                dp[i] = min(dp[i], (dp[j-1]+1 if j>0 else 0))
    return dp[n-1]

# 4. Count palindromic substrings
def count_substrings(s):
    count = 0
    def expand(l, r):
        nonlocal count
        while l >= 0 and r < len(s) and s[l] == s[r]:
            count += 1; l -= 1; r += 1
    for i in range(len(s)):
        expand(i, i)    # odd
        expand(i, i+1)  # even
    return count

# 5. Palindrome Pairs
def palindrome_pairs(words):
    word_map = {w: i for i, w in enumerate(words)}
    result = []
    def is_pal(s): return s == s[::-1]
    for i, word in enumerate(words):
        for j in range(len(word) + 1):
            prefix, suffix = word[:j], word[j:]
            # suffix is palindrome → find reverse of prefix
            if is_pal(suffix):
                rev = prefix[::-1]
                if rev in word_map and word_map[rev] != i:
                    result.append([i, word_map[rev]])
            # prefix is palindrome → find reverse of suffix
            if j != len(word) and is_pal(prefix):
                rev = suffix[::-1]
                if rev in word_map and word_map[rev] != i:
                    result.append([word_map[rev], i])
    return result

# 6. Manacher's Algorithm — O(n)
def manacher(s):
    t = '#' + '#'.join(s) + '#'
    n = len(t)
    p = [0] * n
    center = right = 0
    for i in range(n):
        if i < right:
            p[i] = min(right - i, p[2*center - i])
        while i-p[i]-1 >= 0 and i+p[i]+1 < n and t[i-p[i]-1] == t[i+p[i]+1]:
            p[i] += 1
        if i + p[i] > right:
            center, right = i, i + p[i]
    max_len, center_idx = max((v, i) for i, v in enumerate(p))
    start = (center_idx - max_len) // 2
    return s[start:start + max_len]

if __name__ == '__main__':
    print(longest_palindromic_subseq('bbbab'))  # 4 (bbbb)
    print(min_cut('aab'))                        # 1
    print(count_substrings('abc'))               # 3
    print(count_substrings('aaa'))               # 6
    print(manacher('babad'))                     # bab

"""
Advanced Recursion Patterns
"""

# 1. Generate Parentheses
def generate_parentheses(n):
    result = []
    def backtrack(s, open_count, close_count):
        if len(s) == 2 * n: result.append(s); return
        if open_count < n: backtrack(s + '(', open_count + 1, close_count)
        if close_count < open_count: backtrack(s + ')', open_count, close_count + 1)
    backtrack('', 0, 0)
    return result

# 2. Letter Combinations — Phone Number
def letter_combinations(digits):
    if not digits: return []
    phone = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
    result = []
    def backtrack(idx, path):
        if idx == len(digits): result.append(path); return
        for c in phone[digits[idx]]:
            backtrack(idx + 1, path + c)
    backtrack(0, '')
    return result

# 3. Restore IP Addresses
def restore_ip(s):
    result = []
    def backtrack(start, parts):
        if len(parts) == 4 and start == len(s):
            result.append('.'.join(parts)); return
        if len(parts) == 4 or start == len(s): return
        for length in range(1, 4):
            seg = s[start:start+length]
            if not seg or (len(seg) > 1 and seg[0]=='0') or int(seg) > 255: continue
            backtrack(start + length, parts + [seg])
    backtrack(0, [])
    return result

# 4. Sudoku Solver
def solve_sudoku(board):
    def is_valid(row, col, num):
        box_r, box_c = 3*(row//3), 3*(col//3)
        for i in range(9):
            if board[row][i] == num or board[i][col] == num: return False
            if board[box_r + i//3][box_c + i%3] == num: return False
        return True
    def solve():
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for num in '123456789':
                        if is_valid(r, c, num):
                            board[r][c] = num
                            if solve(): return True
                            board[r][c] = '.'
                    return False
        return True
    solve()

# 5. Expression Evaluation (with backtracking)
def add_operators(num, target):
    result = []
    def backtrack(idx, path, value, prev):
        if idx == len(num):
            if value == target: result.append(path); return
            return
        for end in range(idx + 1, len(num) + 1):
            seg = num[idx:end]
            if len(seg) > 1 and seg[0] == '0': break
            n = int(seg)
            if idx == 0:
                backtrack(end, seg, n, n)
            else:
                backtrack(end, path+'+'+seg, value+n, n)
                backtrack(end, path+'-'+seg, value-n, -n)
                backtrack(end, path+'*'+seg, value-prev+prev*n, prev*n)
    backtrack(0, '', 0, 0)
    return result

if __name__ == '__main__':
    print(generate_parentheses(3))
    print(letter_combinations('23'))
    print(restore_ip('25525511135'))  # ['255.255.11.135','255.255.111.35']
    print(add_operators('123', 6))    # ['1+2+3','1*2*3']

"""
Disjoint Set (Union-Find) — Advanced Applications
"""

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n
        self.components = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # path compression
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py: return False
        if self.rank[px] < self.rank[py]: px, py = py, px
        self.parent[py] = px
        self.size[px] += self.size[py]
        if self.rank[px] == self.rank[py]: self.rank[px] += 1
        self.components -= 1
        return True

    def connected(self, x, y): return self.find(x) == self.find(y)
    def component_size(self, x): return self.size[self.find(x)]

# 1. Number of Connected Components in Undirected Graph
def count_components(n, edges):
    uf = UnionFind(n)
    for u, v in edges: uf.union(u, v)
    return uf.components

# 2. Largest Component Size by Common Factor
def largest_component_size(nums):
    from collections import defaultdict
    uf = UnionFind(max(nums) + 1)
    for num in nums:
        d = 2
        while d * d <= num:
            if num % d == 0: uf.union(num, d); uf.union(num, num // d)
            d += 1
    factor_to_nums = defaultdict(list)
    for num in nums: factor_to_nums[uf.find(num)].append(num)
    return max(len(v) for v in factor_to_nums.values())

# 3. Accounts Merge
def accounts_merge(accounts):
    email_to_id = {}
    uf = UnionFind(len(accounts))
    for i, account in enumerate(accounts):
        for email in account[1:]:
            if email in email_to_id:
                uf.union(i, email_to_id[email])
            email_to_id[email] = i
    from collections import defaultdict
    groups = defaultdict(set)
    for email, i in email_to_id.items():
        groups[uf.find(i)].add(email)
    return [[accounts[i][0]] + sorted(emails) for i, emails in groups.items()]

# 4. Redundant Connection (find cycle edge)
def find_redundant_connection(edges):
    n = len(edges)
    uf = UnionFind(n + 1)
    for u, v in edges:
        if not uf.union(u, v):
            return [u, v]
    return []

# 5. Number of Islands II (dynamic)
def num_islands_ii(m, n, positions):
    uf = UnionFind(m * n)
    active = set()
    count = 0
    result = []
    for r, c in positions:
        idx = r * n + c
        if idx in active:
            result.append(count)
            continue
        active.add(idx)
        count += 1
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            nidx = nr*n+nc
            if 0<=nr<m and 0<=nc<n and nidx in active:
                if uf.union(idx, nidx): count -= 1
        result.append(count)
    return result

if __name__ == '__main__':
    print(count_components(5, [[0,1],[1,2],[3,4]]))   # 2
    print(find_redundant_connection([[1,2],[1,3],[2,3]]))  # [2,3]
    print(num_islands_ii(3, 3, [[0,0],[0,1],[1,2],[2,1],[1,1]]))  # [1,1,2,3,1]
